(function () {
  'use strict';
  const steps = [];
  function chapter(nav, rows, requiresData = true) {
    rows.forEach(row => steps.push({
      id: 'workspace-' + (steps.length + 1), chapter: nav === 'Data' ? 'Input data' : nav,
      nav, target: row[0], title: row[1], copy: row[2], requiresData,
      unavailable: row[3] || '', fallback: row[4] || '', match: row[5] || '',
      wait: row[3] || 'This control or output becomes available when its data and options are ready. You can continue and revisit it.'
    }));
  }
  chapter('Data', [
    ['#data_source', 'Choose the input source', 'Local accepts a file on this computer; URL accepts a supported public link; Import session reopens a saved PASA state; Demo data provides a built-in synthetic example. Example: begin with Demo data while learning, then load your exported wide table.'],
    ['#file', 'Upload a spectrum table', 'Choose CSV, Excel, TSV, or supported text. Put wavelength in nm in column one, sample names in the header, and one sample per remaining column. Example: a table headed nm, Control, Treatment contains two sample curves.', 'Choose Local in Data source to see the file picker.', '#data_source'],
    ['#path', 'Open a link or desktop path', 'Use a supported public Google Sheets or OneDrive link. A local path is accepted only by an explicitly configured desktop launch. Example: paste a public sheet link, inspect its sheets when offered, then click Load data. Hosted sessions cannot read arbitrary server files.', 'Choose URL in Data source.', '#data_source'],
    ['#inspect_url', 'Inspect remote workbook sheets', 'Inspect sheets requests the workbook’s sheet names before loading. Example: choose the measurements sheet instead of a workbook’s cover sheet. Inspection needs network access for a remote source and does not itself load the analysis dataset.', 'Choose URL and provide a supported workbook or sheet link.', '#data_source'],
    ['#sheet, #sheet_ui', 'Select a worksheet', 'The sheet selector appears for relevant workbook sources. Example: select “Day 2” if that worksheet contains the numeric wide table. Ordinary CSV and text files do not contain worksheets.', 'Choose an Excel workbook or supported sheet source.', '#data_source'],
    ['#load', 'Commit the selected input', 'Load data reads and validates the chosen file or link. Selecting a file alone does not finish the import. Example: check the preview and any import message after clicking Load data; an unsuccessful replacement should not be mistaken for new results.', 'Choose Local or URL to see Load data.', '#data_source'],
    ['#load_demo', 'Try the built-in example', 'Load demo data supplies a synthetic table for learning the controls. Example: use its three sample curves to compare an overlay, metrics, and sample similarity. If data are already loaded, review the replacement confirmation first.', 'Choose Demo data to see this button.', '#data_source'],
    ['#state_load', 'Reopen a saved session', 'Choose a PASA session text file, then review which available sections to restore in the dialog. Example: restore only Settings to keep the current input table, or include Input data to restore saved samples too. The tour never applies a restore automatically.', 'Choose Import session in Data source.', '#data_source'],
    ['#pasa_data_preview, #pasa_data_preview_note', 'Check the loaded table', 'The preview shows the first rows and a subset of sample columns; the note gives the full row/sample counts. Example: compare the count with the export you intended to load. A shortened preview does not mean the other columns were discarded.'],
    ['#detected_info', 'Read the detected wavelength information', 'The detected range, step, point count, sample count, and source order help catch import mistakes. Example: an expected 0.5-nm spectrum should not unexpectedly appear as a 5-nm series.', 'Load a dataset to show the detected information.', '#data_source'],
    ['#reset_all', 'Start over deliberately', 'Reset all fields returns the app to its initial state. Example: save your session first if you may need the current choices later. The tour points out this action without clicking it.']
  ], false);
  chapter('Summary', [
    ['#run_summary_ui', 'Read the analysis record', 'Summary brings together the active data, processing choices, warnings, and provenance. Example: after changing baseline from a single wavelength to a window, review this record before interpreting a new plot. A requested setting is not proof that every sample could use it.'],
    ['#preview', 'Review the active table', 'The preview lets you check the data currently in the session. Example: confirm that wavelength is in the first column and that the expected sample names survived import before comparing results.'],
    ['#snapshot_include_settings_summary', 'Save the settings', 'Include Settings to retain the chosen analysis and display options. Example: save a baseline window and normalization choice for reuse with a later dataset. This mirrors the Settings checkbox in Analysis settings.'],
    ['#snapshot_include_data_summary', 'Save the input data', 'Include Input data to carry the active parsed table and supported growth or measured-blank data in the snapshot. Example: include both checkboxes to reopen this analysis later. A parsed table snapshot is not a byte-for-byte copy of the original upload.'],
    ['#dl_state_file_summary', 'Export a reusable session', 'Export session snapshot creates the text file you can reopen from Input data → Import session. Example: save a snapshot before exploring another processing choice; the tour does not download it for you.'],
    ['#dl_summary_pdf, #dl_summary_txt', 'Export a readable summary', 'Summary PDF is convenient for review, while Summary TXT is easy to inspect or archive with notes. Example: send a PDF alongside a plot so the reader can see the settings behind it. Use the session snapshot when you need to restore the analysis.']
  ]);
  chapter('Spectra', [
    ['#plot_spectra, #plot_spectra_3d', 'Read the spectra', 'Compare wavelength, peak position, shape, and signal scale together. Example: two curves may share a peak position but differ in magnitude; normalization can remove that magnitude difference. Use the current-view panel to check the requested scale.'],
    ['#pasa_spectrum_readout', 'Read the current view', 'This panel identifies sample count, wavelength range, and normalization in plain language. Example: “Band peak: Qy, target value: 1” means the selected Qy peak is the scaling reference. Check any processing warnings before assuming it applied to every sample.'],
    ['#customize_titles', 'Customize spectra plot', 'Open this disclosure to find separate groups: Curve style, Titles and axes, Wavelength probe, and Band peaks and labels. Curve style starts open; open another group when you need it. The 3D rendering group appears with 3D overlay. Example: adjust titles without expanding probe settings. Numerical processing remains in Analysis settings.'],
    ['#spectra_3d', 'Explore the 3D waterfall', 'Turn on 3D overlay to separate samples in depth. Drag to rotate, scroll to zoom, and right-drag to pan. Example: use it to inspect three overlapping traces, then turn it off for a flat comparison. This changes presentation, not the underlying sample values.'],
    ['#overlay', 'Overlay or separate samples', 'Curve style contains Overlay samples. It draws curves together; turning it off gives each sample its own facet. Example: use overlay to compare peak positions and facets when many curves conceal one another.', 'Turn off 3D overlay, then open Curve style in Customize spectra plot.', '#spectra_3d'],
    ['#share_y', 'Use comparable facet scales', 'Share Y axis across facets puts separated samples on a common vertical scale. Example: turn it on to compare amplitudes fairly; independent scales reveal small features but can make very different amplitudes look similar.', 'Turn off 3D and Overlay samples to show facet controls in Curve style.', '#overlay, #spectra_3d'],
    ['#palette', 'Choose sample colors', 'The palette in Curve style determines curve colors in 2D and 3D. Example: try Okabe–Ito for distinct categorical curves, or Viridis for an ordered visual progression. The palette does not determine the liquid colors in Sample Color.'],
    ['#line_pattern', 'Distinguish curves by line style', 'Choose all solid, alternating solid/dashed, alternating solid/dotted, or a three-style cycle. Example: alternate solid and dashed when a printed figure may be viewed without color.', 'Turn off 3D overlay for line styles.', '#spectra_3d'],
    ['#line_width', 'Set line thickness', 'Line width controls how strongly a 2D curve is drawn. Example: increase it for a slide viewed at a distance, or reduce it when many curves overlap. It does not smooth or alter a curve.', 'Turn off 3D overlay to see line width.', '#spectra_3d'],
    ['#title_x_axis', 'Name the wavelength axis', 'Titles and axes groups the four title fields with axis and shading controls. An empty title uses the app default. Example: enter “Wavelength (nm)” to state the coordinate and unit explicitly. Renaming an axis does not convert its units.', 'Turn off 3D overlay, then open Titles and axes in Customize spectra plot.', '#spectra_3d'],
    ['#title_y_axis', 'Name the signal axis accurately', 'Use a title matching the actual numerical basis. Example: “Normalized signal” is more appropriate than claiming absorbance concentration after a scale normalization. Leaving it blank uses PASA’s default.', 'Turn off 3D to use the custom title fields.', '#spectra_3d'],
    ['#title_chart', 'Give the figure context', 'The chart title names the displayed comparison. Example: “Control and treatment, 24 h” tells a reader what the curves represent. Avoid interpreting the treatment effect from a title alone.', 'Turn off 3D to use the custom title fields.', '#spectra_3d'],
    ['#title_legend', 'Name the legend', 'The legend title explains what the listed curve names identify. Example: use “Sample” or “Condition” according to your naming scheme, or leave it blank for the default.', 'Turn off 3D to use the custom title fields.', '#spectra_3d'],
    ['#x_axis_intensity', 'Adjust the horizontal axis', 'X-axis intensity controls the visibility of the horizontal axis line. Example: reduce it for a lighter figure while keeping labels readable. It does not change wavelength limits.', 'This is a 2D appearance setting.', '#spectra_3d'],
    ['#y_axis_intensity', 'Adjust the vertical axis', 'Y-axis intensity controls the vertical axis line. Example: use a stronger line when a figure is projected against a bright background. It does not change the measured signal scale.', 'This is a 2D appearance setting.', '#spectra_3d'],
    ['#gridline_intensity', 'Control gridline prominence', 'Fainter gridlines help the curves stand out; stronger ones aid approximate coordinate reading. Example: try a light grid for an overview, then use the numerical probe for a precise reported value.', 'This is a 2D appearance setting.', '#spectra_3d'],
    ['#band_fill_intensity', 'Control band-window shading', 'This slider changes how strongly the configured band regions are shaded. Example: increase it while explaining where Qy and Soret windows lie, then reduce it for a crowded overlay. Window limits themselves are edited in Analysis settings.', 'This is a 2D appearance setting.', '#spectra_3d'],
    ['#show_probe_line', 'Inspect a chosen wavelength', 'Open Wavelength probe, then enable Show wavelength probe to show its indicator and values table. Opening the group alone does not enable the probe. Example: inspect 680 nm across all selected samples. A probe is a coordinate readout, not a fitted peak search.'],
    ['#probe_nm', 'Enter the probe wavelength', 'Type the coordinate you want to inspect, in nm. Example: enter 680 to compare the selected samples at that wavelength. Respect the measured range and the app’s support rules.', 'Open Wavelength probe and enable Show wavelength probe.', '#show_probe_line'],
    ['#probe_step', 'Choose a useful probe increment', 'Step size (nm) controls the increment for the probe slider. Example: use 0.5 nm for a finely sampled trace or 5 nm for a quick sweep. It does not increase the resolution of the instrument data.', 'Open Wavelength probe and enable Show wavelength probe.', '#show_probe_line'],
    ['#probe_slider', 'Move the probe interactively', 'Use Move the probe to slide through the available range; it stays linked to the numerical wavelength field. Example: slide across the Qy window to inspect how the sample readouts change.', 'Open Wavelength probe and enable Show wavelength probe.', '#show_probe_line'],
    ['#probe_color', 'Keep the probe visible', 'Auto follows the default appearance; Blue or Red offers a contrasting probe line. Example: choose red when the sample curves are predominantly blue.', 'Open Wavelength probe and enable Show wavelength probe.', '#show_probe_line'],
    ['#probe_after_norm', 'Compare probe values before and after normalization', 'Also show after-normalization values adds the scaled readout. Example: compare the pre-normalization value with the target-scaled curve at 680 nm. The difference is a processing choice, not an additional measurement.', 'Choose a normalization method in Analysis settings. Then open Wavelength probe and enable Show wavelength probe.', '#show_probe_line'],
    ['#probe_table', 'Read the probe values table', 'The table reports available values for the selected coordinate and samples. Example: use this table instead of estimating a number from the plot. Unsupported values should be read with the range and processing messages.', 'Open Wavelength probe, enable Show wavelength probe and load usable samples.', '#show_probe_line'],
    ['#show_peaks', 'Inspect band peaks', 'Open Band peaks and labels, then enable Show band peaks to inspect maxima within configured windows. Opening the group alone does not turn peak marks on. Example: select Qy and Soret to compare their reported coordinates. These window-based descriptors do not establish pigment identity.'],
    ['#peak_bands, #peak_band_selector', 'Choose bands to mark', 'Tick the bands whose maxima you want to inspect. Example: select Qy and Soret for a focused comparison rather than marking every overlapping window.', 'Open Band peaks and labels and enable Show band peaks.', '#show_peaks'],
    ['#show_peak_points_on_plot', 'Show peak points', 'This checkbox adds or removes peak-point markers on the graph. Example: leave the table available but turn the markers off for a cleaner curve figure.', 'Open Band peaks and labels and enable Show band peaks.', '#show_peaks'],
    ['#lbl_point_opts', 'Control the information on peak labels', 'Peak label content separates four pieces of text so you can keep the figure readable. Example: a crowded overlay may need only sample and wavelength, whereas a teaching figure may also need the band name.', 'Open Band peaks and labels and enable Show band peaks.', '#show_peaks'],
    ['#lbl_curve', 'Label the sample', 'Sample name adds the curve identity to peak labels. Example: retain it when several samples share nearly the same peak position.', 'Open Band peaks and labels, enable Show band peaks, then open Peak label content.', '#lbl_point_opts, #show_peaks'],
    ['#lbl_band', 'Label the band window', 'Band name adds the configured window label. Example: show Qy and Soret labels when explaining which maxima are being compared.', 'Open Band peaks and labels, enable Show band peaks, then open Peak label content.', '#lbl_point_opts, #show_peaks'],
    ['#lbl_nm', 'Label peak wavelength', 'λ (nm) adds the reported peak coordinate. Example: keep this on to compare positions without repeatedly reading the axis.', 'Open Band peaks and labels, enable Show band peaks, then open Peak label content.', '#lbl_point_opts, #show_peaks'],
    ['#lbl_val', 'Label peak value', 'Value adds the peak’s numerical signal to the label. Example: turn it on for one or two curves, but use the table when values would overlap.', 'Open Band peaks and labels, enable Show band peaks, then open Peak label content.', '#lbl_point_opts, #show_peaks'],
    ['#peaks_layout', 'Arrange the peak table', 'With at least two selected bands, choose a stacked table or a separate table per band. Example: separate by band to compare the Qy peak across many samples.', 'Open Band peaks and labels, enable Show band peaks and select at least two bands.', '#peak_bands, #show_peaks'],
    ['#peaks_block', 'Read the band peak outputs', 'Use the peak tables for coordinates and values at the configured processing basis. Example: compare Qy peak positions alongside their band-window limits and the normalization setting.', 'Open Band peaks and labels, enable Show band peaks and select a band.', '#show_peaks'],
    ['#spectra_3d_opacity', 'Set 3D ridge transparency', 'Lower fill opacity lets rear ridges show through; higher opacity makes individual surfaces more solid. Example: reduce it when a front sample hides another curve.', 'Turn on 3D overlay and open the 3D rendering group in Customize spectra plot.', '#spectra_3d'],
    ['#spectra_3d_res', 'Balance 3D detail and responsiveness', 'Resolution caps displayed points per curve. Example: lower it for a large collection on a slower laptop, then inspect the original numerical exports for full detail. This cap affects presentation.', 'Turn on 3D overlay and open 3D rendering in Customize spectra plot.', '#spectra_3d'],
    ['#spectra_3d_label_dist', 'Place 3D sample labels', 'Sample-label distance offsets labels in pixels. Example: increase it when names overlap the edge of the ridges.', 'Turn on 3D overlay and open 3D rendering in Customize spectra plot.', '#spectra_3d'],
    ['#spectra_3d_probe_opacity', 'See the 3D probe plane', 'Probe plane opacity changes the transparency of the wavelength plane. Example: make it faint enough to see the sample ridges behind it.', 'Turn on 3D overlay, enable Show wavelength probe in Wavelength probe, and open 3D rendering.', '#show_probe_line'],
    ['#spectra_3d_export_scale', 'Choose 3D export resolution', 'The export multiplier increases the image dimensions. Example: use a larger multiplier when a figure will be enlarged in a presentation; it uses more rendering memory.', 'Turn on 3D overlay and open 3D rendering in Customize spectra plot.', '#spectra_3d'],
    ['#enlarge_spectra', 'Inspect a larger plot', 'Enlarge opens a larger view for inspection. Example: use it when curve labels crowd the workspace. Close the enlarged view to return to the tab; the tour does not open it automatically.'],
    ['#spectra_top_dl_pdf, #spectra_top_dl_img', 'Save the spectrum figure', 'Download as PDF and Download as Image save the current supported figure. Example: choose PDF for a document workflow or an image for slides. Save a session or summary as well when the figure needs reproducible settings.']
  ]);
  chapter('Metrics', [
    ['#metrics_layout', 'Arrange the metrics tables', 'Choose stacked rows, a single table by band, or separate tables per band. The band layouts offer versions with or without column spanners. Example: use separate band tables when comparing the Qy measurements across samples; use a stacked table for an analysis record.'],
    ['#metrics_ui .pasa-metrics-scroll-tools, #metrics_ui .pasa-metrics-pan-left, #metrics_ui .pasa-metrics-pan-right, #metrics_ui .pasa-metrics-scroll-viewport', 'Move across a wide metrics table', 'When a table is wider than its viewport, use the synchronized top and bottom horizontal scrollbars or click the translucent left/right arrows to move across columns. Example: inspect later sample columns without scrolling to the table’s bottom. Focus a scrollbar for Arrow Left/Right or Home/End navigation. Controls hide when no horizontal overflow is present.', 'Load a wide metrics table or choose a layout with enough columns to require horizontal scrolling.', '#metrics_layout'],
    ['#metrics_ui', 'Read each metric on its own basis', 'The table distinguishes pre-normalization areas and peak coordinates from values that depend on normalization. Example: compare peak wavelength for shape position, and inspect pre-normalization AUC when magnitude matters. Grayed or missing results need their stated reasons.'],
    ['.metrics-ratio-note', 'Understand band ratios', 'The ratio note explains numerator and denominator conventions. Example: a ratio can become large because its denominator is small; inspect both bands and their windows before attributing a physical cause.'],
    ['#copy_metrics_table, #copy_metrics_notify', 'Copy a complete table', 'Copy the entire table prepares tab-separated data for a spreadsheet and reports success or failure. Example: paste into a blank spreadsheet to keep columns aligned. A clipboard action is separate from saving a file.'],
    ['#dl_metrics_xlsx, #dl_metrics_pdf', 'Save metrics for further work', 'XLSX is convenient for spreadsheet analysis; PDF is a formatted report for reading. Example: retain the numeric file with the session snapshot and use PDF for review.']
  ]);
  chapter('Band AUC', [
    ['#auc_basis', 'Choose the integrated curve basis', 'Choose Raw (dilution-scaled), Baseline-corrected, Baseline + smoothed, or Baseline + smoothed + normalized. Example: compare pre-normalization areas for signal magnitude and normalized areas for an appropriate shape comparison. The note below states the effective basis; when baseline correction is off, only the raw basis is meaningful.'],
    ['#auc_basis_disclosure', 'Check what the basis uses', 'This description explains native-grid versus processed-grid integration and the selected processing basis. Example: after enabling smoothing, confirm whether this AUC view uses smoothed values before comparing it with an earlier export.'],
    ['#auc_what_shows', 'Understand the AUC display', 'Open this explanation to see how band areas are presented. Example: overlapping band windows can count the same wavelength region twice; do not add overlapping band AUCs as though they were disjoint.'],
    ['#auc_chart_type', 'Compare bar and radar views', 'Bar chart uses one panel per sample; Radar/spider chart emphasizes relative band balance and requires enough active bands. Example: use bars to compare numeric area heights, then radar for a compact pattern overview.'],
    ['#auc_common_y', 'Share the bar-chart scale', 'A common Y-axis makes bar heights comparable across samples. Example: keep it on when comparing signal magnitude; independent axes can make a small-area sample appear as tall as a large-area one.', 'Select Bar chart.', '#auc_chart_type'],
    ['#auc_overlay', 'Overlay radar traces', 'Overlay all samples in one panel makes radar patterns easy to compare. Example: overlay a control and two treatments; turn it off when many polygons become difficult to read.', 'Select Radar / spider chart.', '#auc_chart_type'],
    ['#auc_plot_ui, #plot_auc', 'Read the AUC plots', 'Read each band label, basis, and axis scale alongside the plotted area. Example: compare the Qy bar between samples only after checking that they share the intended scale and processing basis.'],
    ['#enlarge_auc', 'Enlarge a band-area plot', 'Enlarge gives a larger view of the available AUC chart. Example: use it to read long sample names before export.', 'A supported AUC chart must be available.', '#auc_chart_type'],
    ['#auc_bar_dl_pdf, #auc_bar_dl_img, #auc_radar_dl_pdf, #auc_radar_dl_img', 'Export a band-area figure', 'PDF and Image buttons save the matching bar or radar figure. Example: export the bar figure with shared axes for a magnitude comparison and retain the numeric metrics table alongside it.']
  ]);
  chapter('Data Quality', [
    ['#qc_banner', 'Read the quality-screen context', 'These diagnostics are review prompts, not certification that a sample is acceptable. Example: investigate a flag using blanks, instrument performance, and experimental provenance rather than automatically deleting that sample.'],
    ['#noise_qc_verdicts', 'Review noise verdicts', 'The operational noise screen reports its available assessments and insufficient-support states. Example: an unevaluable short spectrum is not a PASS. The thresholds are editable development defaults.'],
    ['#noise_qc_chart', 'Compare noise components', 'The chart helps identify which noise indicators are prominent. Example: a local issue may deserve inspection even when a whole-spectrum indicator is small; it does not identify the physical cause.'],
    ['#noise_qc_strips', 'Locate noisy intervals', 'The interval display directs attention to affected wavelength regions. Example: inspect an isolated rough section against the raw curve and acquisition record before deciding whether it is an artifact.'],
    ['#noise_qc_show_tables', 'Open detailed noise diagnostics', 'Show detailed QC tables reveals the numerical noise components, intervals, and thresholds. Example: use the tables to understand why a sample received its displayed category.'],
    ['#noise_qc_metrics_table', 'Inspect per-sample noise numbers', 'This table records component values and the support used to evaluate each sample. Example: compare two samples only after checking whether both had enough usable support.', 'Enable Show detailed QC tables in the noise section.', '#noise_qc_show_tables'],
    ['#noise_qc_interval_table', 'Inspect flagged intervals numerically', 'The interval table locates wavelength spans implicated by the screen. Example: use its bounds to revisit a short rough region in Spectra.', 'Enable the detailed noise tables.', '#noise_qc_show_tables'],
    ['#noise_qc_components_table', 'Inspect the contributing components', 'The component table separates the terms behind the noise assessment. Example: compare global, tail, and local contributions instead of treating one composite number as a diagnosis.', 'Enable the detailed noise tables.', '#noise_qc_show_tables']
  ]);
  const thresholds = [
    ['nqc_global_caution','Global CAUTION','0.5%','global'], ['nqc_global_fail','Global FAIL','1.5%','global'],
    ['nqc_tail_caution','Tail CAUTION','1.0%','tail'], ['nqc_tail_fail','Tail FAIL','3.0%','tail'],
    ['nqc_local_caution','Local CAUTION','0.75%','local'], ['nqc_local_fail','Local FAIL','2.5%','local'],
    ['nqc_frac_caution','Fraction CAUTION','0.20','fraction'], ['nqc_frac_fail','Fraction FAIL','0.50','fraction']
  ];
  chapter('Data Quality', thresholds.map(t => ['#'+t[0], 'Set '+t[1]+' deliberately',
    'This is the editable '+t[1]+' boundary for the '+t[3]+' noise indicator. The packaged value '+t[2]+' is an example of an operational development setting, not a validated acceptance limit. Set it from suitable controls and keep CAUTION below FAIL.',
    'Enable the detailed noise tables to inspect thresholds.', '#noise_qc_show_tables']));
  chapter('Data Quality', [
    ['#nqc_threshold_warn, #noise_qc_thresholds', 'Check the threshold explanation', 'The threshold display records the active settings and warns about invalid ordering. Example: if CAUTION is greater than or equal to FAIL, correct the pair rather than interpreting the labels as a consistent severity scale.', 'Enable the detailed noise tables.', '#noise_qc_show_tables'],
    ['#qc_view', 'Choose per-sample checks or pair comparisons', 'Per-sample QC asks which individual traces merit review. Sample similarity compares spectral shapes between pairs. Its controls are grouped into Network appearance, Labels and visible connections, Calculation limit, and How similarity is calculated. Example: start with Network appearance, then open another group when you need it.'],
    ['#qc_show_tables', 'Show detailed QC or similarity tables', 'This checkbox reveals the detailed table for the selected view and the associated information. Example: turn it on when you need exact pair values rather than the network overview.'],
    ['#qc_baseline_tol', 'Set the baseline-residual review threshold', 'The per-sample threshold group contains the review limits. Baseline residual tolerance flags an offset within the documented diagnostic bounds. Example: compare its 0.005 starting value with blank variability appropriate to your experiment; it is not a universal instrument specification.', 'Select Per-sample QC and open its threshold group above the chart.', '#pasa-qc-thresholds, #qc_view'],
    ['#qc_sat_thresh', 'Set a high-signal review threshold', 'The saturation threshold prompts review of large raw values; it does not diagnose detector saturation. Example: choose a threshold based on the validated linear range of your instrument instead of assuming the 2.5 starting value is universal.', 'Select Per-sample QC and open its threshold group above the chart.', '#pasa-qc-thresholds, #qc_view'],
    ['#qc_dup_cor', 'Review highly correlated inputs', 'The duplicate-detection cutoff flags very-high-correlation pairs for provenance review. Example: a pair above the 0.9999 starting cutoff may be repeated data or simply very similar curves; correlation alone does not establish identity.', 'Select Per-sample QC and open its threshold group above the chart.', '#pasa-qc-thresholds, #qc_view'],
    ['#qc_chart, #qc_chart_interpretation', 'Interpret the residual chart', 'The chart’s colors refer to its baseline-residual screen, not an overall certificate of data quality. Example: read the interpretation below it before equating a green bar with an acceptable sample.', 'Select Per-sample QC.', '#qc_view'],
    ['#qc_table, #qc_heading', 'Read the per-sample inventory', 'The table inventories loaded samples and distinguishes evaluated rows from deselected or unevaluable rows. Example: a deselected sample marked Not evaluated must not be counted as passing.', 'Select Per-sample QC and show its detailed tables.', '#qc_view'],
    ['#sim_layout', 'Arrange the similarity network', 'Network appearance starts open and contains the layout and relationship metric. Bubbles, Force-directed, and Circular arrange the same comparison graph. Example: a circular view separates long labels; a force-directed view can help inspect groups. Layout position is not another measured metric.', 'Select Sample similarity (shape-based) and open Network appearance.', '#pasa-sim-appearance, #qc_view'],
    ['#sim_metric', 'Choose what edge thickness represents', 'In Network appearance, select weighted spectral angle, weighted derivative correlation, or weighted pre-normalization correlation. Example: use spectral angle to inspect angular shape difference. Edge color still follows the combined operational verdict and may not mirror the chosen thickness metric.', 'Select Sample similarity (shape-based) and open Network appearance.', '#pasa-sim-appearance, #qc_view'],
    ['#sim_show_node_names', 'Label the network nodes', 'Open Labels and visible connections to find Show sample names on nodes. It keeps each node identifiable. Example: turn it off for a dense overview, then use the table to identify pairs. Opening the group does not change the checkbox.', 'Select Sample similarity (shape-based) and open Labels and visible connections.', '#pasa-sim-labels, #qc_view'],
    ['#sim_show_edge_values', 'Label the pair values', 'Show edge values, in Labels and visible connections, adds the selected metric to network links. Example: enable it for three samples, but hide it for a dense graph where labels overlap.', 'Select Sample similarity (shape-based) and open Labels and visible connections.', '#pasa-sim-labels, #qc_view'],
    ['#sim_edge_range, #sim_edge_range_ui', 'Filter which similarity links are shown', 'In Labels and visible connections, Edge strength range retains links whose strength falls inside its two handles. Example: move the left handle right to hide weaker links, or lower the right handle to inspect moderate links. Nodes remain; computed metrics do not change. The full range includes eligible links before the disclosed browser display limit.', 'Select Sample similarity (shape-based) with at least two usable samples, then open Labels and visible connections.', '#pasa-sim-labels, #qc_view'],
    ['#sim_pair_budget', 'Keep pairwise work manageable', 'Open Calculation limit to find the trace budget. It limits how many selected traces may enter the pairwise calculation. Maximum (1600) still has a 1600-trace ceiling and a wavelength-work safety limit; an explicit override cannot remove those limits. Example: 15 traces produce 105 pairs; a much larger selection grows quickly. PASA refuses an over-budget calculation instead of silently truncating it. The budget status remains visible when this group is closed.', 'Select Sample similarity (shape-based) and open Calculation limit.', '#pasa-sim-budget, #qc_view'],
    ['#sim_budget_status, #sim_compute_anyway', 'Read the comparison budget status', 'The status reports whether the requested comparison fits the budget and may offer an explicit larger calculation. Example: reduce selected samples or deliberately request more work after considering the count. The tour does not start an override.', 'Select Sample similarity (shape-based).', '#qc_view'],
    ['#sim_projection_status', 'Distinguish display limits from calculation limits', 'Projection information explains how the network/table presentation relates to the computed pairs. Example: read this message before assuming that every relationship can be displayed at once.', 'Select Sample similarity (shape-based).', '#qc_view'],
    ['#similarity_network_ui, #similarity_visnet, #similarity_ggraph, #similarity_table_fallback, #pasa-sim-method', 'Read the shape relationships and method', 'The display compares spectral shapes; a table is used when the interactive network is unavailable. Use Next field to reach How similarity is calculated. This group explains pair-local shared wavelength support, weighted correlation and angle, operational tiers, and the advisory derivative metric. Example: high correlation and low angle suggest close shape agreement, not matching concentrations or confirmed identity. Open the method group whenever you need its assumptions.', 'Select Sample similarity; at least two usable samples are needed for the network. Open How similarity is calculated to read the method.', '#pasa-sim-method, #qc_view'],
    ['#similarity_table', 'Inspect pair metrics and reasons', 'The detailed table records each supported pair’s metrics and the reasons values may be unavailable. Example: inspect an apparently unusual edge numerically and check both spectra’s support.', 'Select Sample similarity and enable Show detailed QC tables.', '#qc_show_tables'],
    ['#dl_qc_csv', 'Save the QC report', 'Download QC report keeps the numerical diagnostics for later review. Example: archive it with the input data and processing snapshot so operational thresholds can be understood later.']
  ]);
  chapter('Sample Color', [
    ['#is_pigmented', 'Choose whether to show the color illustration', 'Declare whether this color view is relevant to the sample. Example: choose Yes to explore the illustrative mapping of a pigmented sample. The app does not determine pigment identity from this answer.'],
    ['#cuv_sample, #cuv_scene_background', 'Choose a sample and scene background', 'The sample selector chooses the curve supplying the illustrative color. Use Next field to reach Scene background. Choose Dark or Light for the cuvette scene independently of the app theme. Example: compare the same sample against both backgrounds to inspect the transparent liquid; the calculated color and hex code stay the same. Dark is the starting choice.', 'Choose Yes for the sample-color question.', '#is_pigmented'],
    ['#cuv_od', 'Set the rendering reference target', 'The target rescales the selected numerical reference feature for the illustration. Example: use a target of 1 to compare shapes at a common reference scale; this is not a measured concentration or path length.', 'Choose Yes for the sample-color question.', '#is_pigmented'],
    ['#cuv_actual_od', 'Keep the final curve’s scale', 'Use the final analysis curve without reference rescaling skips the extra color-reference scaling. Example: enable it to retain the final curve scale; any earlier analysis normalization still remains part of that curve.', 'Choose Yes for the sample-color question.', '#is_pigmented'],
    ['#cuv_show_all', 'Compare all selected sample colors', 'Show all sample colors places one labeled cuvette per selected sample on the bench. Example: with 15 selected samples, the view wraps them into rows according to the available width; no extra samples are invented.', 'Choose Yes for the sample-color question.', '#is_pigmented'],
    ['#cuvette_plot, #cuvette_grid', 'Read the cuvette illustration', 'The static bench and lighting help show transparent liquid. Sample names identify each cuvette. Expand Color details below the image to find the calculated color values. Example: use the table for an exact sRGB reference and the glass scene for illustration; PASA does not predict a calibrated physical cuvette appearance.', 'Choose Yes and load usable samples.', '#is_pigmented'],
    ['#cuv_fallback_warn, #pasa-color-interpretation', 'Read the color limitations', 'The notes identify the rendering basis, numerical reference, weak-signal treatment, and any endpoint-held wavelength spans. Example: a spectrum ending before 780 nm does not supply measured color information over the missing interval.', 'Choose Yes for the sample-color question.', '#is_pigmented'],
    ['#cuvette_grid_metadata', 'Expand Color details', 'Color details starts collapsed below the image. Open it to read the exact sample name, calculated sRGB hex code, and rendering information. The table shows your chosen sample, or all displayed samples when Show all sample colors is enabled. Example: copy a hex code for a color reference or check the full name when a bench label is shortened.', 'Choose Yes, load usable samples, then open Color details below the image.', '#pasa-color-details, #is_pigmented']
  ]);
  chapter('Data Quality', [
    ['#advanced_mode', 'Reveal the advanced analysis tab', 'Advanced Mode adds Deconvolution after Data Quality. Example: switch it on when you want to inspect overlapping fitted components, then visit that chapter. The tour explains the controls without starting a fit or changing this switch.']
  ], false);
  chapter('Summary', [
    ['#pasa-settings-shortcut', 'Return to analysis settings from a result', 'The Analysis settings shortcut takes you straight to the dedicated settings tab. Example: return there to adjust a band window after reviewing Metrics. The shortcut is available on analysis pages and is hidden on Welcome and the information pages.'],
    ['#dl_state_file', 'Save a reusable session', 'Save session writes the settings and data sections you chose in Session snapshot. Example: save before trying another processing approach so you can return to this analysis later. The tour does not initiate downloads.'],
    ['.pasa-export-menu', 'Find the export shortcuts', 'Export groups the complete ZIP download and links to tables and the analysis summary. Example: use the summary link for a concise report, or the ZIP when you want the applicable outputs together.'],
    ['#dl_all_zip', 'Archive the available results together', 'Download everything includes applicable tables, figures, reports, and a full session snapshot. Example: keep the ZIP alongside your original instrument export. The snapshot preserves the parsed active table and PASA state, rather than every byte of the original file formatting.']
  ], false);
  chapter('About', [
    ['#pasa-about-content', 'Get oriented in About', 'About introduces PASA, the kinds of spectra it supports, and the meaning of its analysis views. Example: start here to understand how direct band integration differs from model-based deconvolution.'],
    ['[data-pasa-disclosures="pasa-about-content"]', 'Expand or collapse the About page', 'Expand all opens every section; Collapse all folds them away. You can also open one heading at a time. Example: expand the input-format section while preparing a first file.'],
    ['#pasa-about-content summary', 'Check the required input layout', 'The Input data format section describes a wide table: wavelength first, then one column per sample. Example: use nm, Control, Treatment as column headings and keep each row aligned at the same wavelength.', '', '', 'Input data format'],
    ['#pasa-about-content summary', 'Check file types and wavelength spacing', 'CSV, Excel and tab-delimited text are supported. The wavelength-spacing notes explain detection and optional resampling. Example: retain an evenly spaced 0.5-nm source grid unless you have a reason to resample.', '', '', 'Wavelength increment'],
    ['#demo_format_preview', 'Inspect a concrete wide-table example', 'This example shows how wavelengths and sample values line up. Example: compare its first column and header row with your export before importing. Values should remain numeric; sample names belong in the header.'],
    ['#dl_template', 'Download a blank input template', 'The CSV template supplies the expected arrangement. Example: paste wavelengths into the first column and one sample into each following column, keeping the header row.'],
    ['#pasa-about-content summary', 'Compare integration and fitted components', 'Band AUC sums the measured signal inside fixed windows. Deconvolution partitions a modeled curve among overlapping components. Example: use a window area to describe a chosen interval, and a fit to investigate one possible component representation.', '', '', 'How it differs'],
    ['#pasa-about-content summary', 'Read the limits of interpretation', 'A fitted component is a description of curve shape, not proof of a pigment or its concentration. Example: corroborate an apparent band assignment with suitable standards or independent measurements.', '', '', 'Honesty caveat']
  ], false);
  chapter('Help', [
    ['#help_content', 'Use the full Help manual', 'Help gives the operating instructions and science reference in one place. Example: open the section matching the setting you are changing, and consult its assumptions before interpreting a result.'],
    ['[data-pasa-disclosures="help_content"]', 'Open all Help sections or focus on one', 'Expand all makes the complete manual readable; Collapse all leaves a compact list of headings. Example: expand everything when searching the page for a term such as normalization.'],
    ['#help_content summary', 'Find loading instructions', 'Input / Data Loading explains source routes, worksheet selection, missing values, and format requirements. Example: revisit it when a workbook contains several sheets or an imported table has an unexpected sample count.', '', '', '1. Input'],
    ['#help_content summary', 'Read the baseline contract', 'Baseline Correction explains the requested reference and the native measured points actually used. Example: inspect the effective reference when a requested wavelength is between two measured nodes.', '', '', '2. Baseline'],
    ['#help_content summary', 'Understand conditioning choices', 'Signal Conditioning / Smoothing documents resampling and smoothing. Example: check how a smoothing window relates to your wavelength spacing before interpreting a narrow feature.', '', '', '3. Signal'],
    ['#help_content summary', 'Understand scaling and normalization', 'Scaling / Normalization explains dilution factors, normalization references, and the loss of amplitude information. Example: compare shapes at a common band peak while retaining the pre-normalization metrics for amplitude comparisons.', '', '', '4. Scaling'],
    ['#help_content summary', 'Read the adaptive band definitions', 'Bands / Metrics documents how organism and preparation change the available band windows and reported measurements. Example: review it when a Chl b or phycoerythrin field appears after changing the preset.', '', '', '5. Bands'],
    ['#help_content summary', 'Find plot and export instructions', 'Plots / Tabs / QC / Exports explains the available figures, probe and peak readouts, quality views and downloads. Example: consult this section when deciding which exported table or figure records the basis you want to report.', '', '', '6. Plots'],
    ['#help_content summary', 'Find the quality and similarity explanations', 'The Data Quality section distinguishes checks on individual traces from pairwise shape comparisons. Example: read it before interpreting a network edge as biological identity.', '', '', '6a. Data Quality'],
    ['#help_content summary', 'Review growth assumptions', 'Cell Growth explains the OD source, equidistant time mapping, fitting windows, and apparent rate interpretation. Example: check replicate and time ordering before comparing growth rates.', '', '', '7. Cell Growth'],
    ['#help_content summary', 'Understand session restoration', 'Save / reload session explains the sections you can restore. Example: restore only Settings to reuse a processing setup while keeping the current input data.', '', '', '8. Save'],
    ['#help_content summary', 'Read the advanced fitting guide', 'The deconvolution guide explains the fit basis, bounds, model selection, uncertainty, and diagnostics. Example: consult it when two component counts give similarly good curve descriptions.', '', '', '9. Advanced'],
    ['#help_content summary', 'Consult the science reference', 'The Science Reference groups background on band assignments, baseline correction, Beer–Lambert assumptions, the Qy convention, color illustration and sample similarity. Example: read the relevant assumptions before translating a spectral descriptor into a biological claim.', '', '', 'Science Reference'],
    ['#help_content summary', 'Distinguish operational defaults from established limits', 'The operational-defaults section identifies configurable development settings. Example: a default quality threshold is a starting point for review, not a validated acceptance rule for your experiment.', '', '', 'Operational defaults']
  ], false);
  chapter('FAQ', [
    ['#pasa-faq-main', 'Browse the practical questions', 'Frequently Asked Questions gives short answers to common loading, processing, plotting, and export questions. Example: start here when a setting or result behaves differently from what you expected.'],
    ['#pasa-faq-main + div button', 'Expand or collapse every FAQ answer', 'Expand all opens both the practical and advanced answers; Collapse all folds them away. Example: expand the page before using your browser’s text search for “normalization”, or keep it collapsed to scan the questions. Individual question headings can also be opened separately.'],
    ['#faq_accordion details', 'Find the file-format answer', 'The format answer explains the first wavelength column and the sample columns, with a link to the About example and template. Example: check it when deciding whether to transpose an instrument export.', '', '', 'How do I format my input file?'],
    ['#faq_accordion details', 'Learn with the built-in data', 'The demo answer shows how to explore PASA without preparing a file. Example: use Demo data in Input data to try three synthetic curves before analyzing your measurements.', '', '', 'Do I have to use my own data'],
    ['#faq_accordion details', 'Understand what normalization changes', 'This answer explains shape comparisons, amplitude loss, and the baseline requirement. Example: a Qy target of 1 scales the final curve while pre-normalization metrics retain their documented basis.', '', '', 'When should I normalize'],
    ['#faq_accordion details', 'Check how band windows are chosen', 'Band windows are editable starting points that depend on organism and sample type. Example: check the preset and reference spectrum before interpreting the third band as PBS or chlorophyll b.', '', '', 'How are the Qy'],
    ['#faq_accordion details', 'Find the Cell Growth introduction', 'This answer explains manual entry, spectra-based OD, time spacing, replicates, and the main outputs. Example: manual OD entry lets you explore the growth workflow independently of a loaded spectrum.', '', '', 'How does the Cell Growth tab work?'],
    ['#faq_accordion details', 'Find the answer about session files', 'The session answer explains settings, input data, growth entries, and measured blanks. Example: use a session snapshot to continue later, and retain the original instrument file separately.', '', '', 'How do I save and reload'],
    ['#pasa-faq-advanced', 'Browse the Advanced Mode questions', 'Advanced Mode & Deconvolution has its own FAQ group. Example: read these answers before treating an apparently excellent overlay as evidence that the model components are unique.'],
    ['#faq_accordion details', 'Learn how deconvolution differs from AUC', 'The answer contrasts direct integration over a fixed window with area assigned to a model component. Example: overlapping fitted peaks can share a wavelength interval that the AUC view simply integrates together.', '', '', 'How is deconvolution different'],
    ['#faq_accordion details', 'Read what fitted bands can establish', 'The interpretation answer explains why a good curve fit cannot establish pigment identities or concentrations on its own. Example: compare plausible assignments with authenticated standards and other study evidence.', '', '', 'Can I trust the fitted bands'],
    ['#faq_accordion details', 'Understand disagreement between selection scores', 'This answer explains the component-count search and conditional parsimony scores. Example: if AIC-like and BIC-like preferences differ, inspect bounds and residuals instead of assuming one count is proven.', '', '', 'How does the app choose the number']
  ], false);
  chapter('References', [
    ['#references_content', 'Find the sources behind the methods', 'References groups citations by method. Example: use the smoothing reference when documenting processing, or the growth reference when reporting an apparent OD-derived rate.'],
    ['#references_content h4', 'Trace the color illustration basis', 'The CIE and D65 references describe the numerical basis for the illustrative color mapping. Example: cite the mapping appropriately while distinguishing a screen illustration from a calibrated physical appearance.', '', '', 'CIE 1931'],
    ['#references_content h4', 'Check the deconvolution-default explanation', 'This section distinguishes methodological background from configurable thresholds and band-width defaults. Example: document material departures from defaults and assess the fit sensitivity.', '', '', 'Deconvolution thresholds']
  ], false);
  chapter('Feedback', [
    ['#pasa-feedback-panel', 'Share your experience with PASA', 'Feedback is the place for a reaction, a problem report, or an improvement idea. Example: describe which tab you used, what you expected, and what happened. Your feedback can help prioritize the next version.'],
    ['#pasa-feedback-rating', 'Choose an experience rating', 'Choose the reaction that best describes your experience. Example: a positive rating can still accompany a suggestion for a clearer label or an easier workflow.'],
    ['#fb_comment', 'Write a useful problem report or suggestion', 'Add enough detail to explain the issue. Example: “Metrics: with 15 samples, I want to scroll horizontally from the top.” For a reproducibility problem, include the relevant settings and a small shareable example when appropriate.'],
    ['#fb_compose_email', 'Optionally review an email draft', 'Compose email is an alternative to the direct form. It prepares your rating, comment, and app version in your mail application. You review and send it there using your email identity. Example: use email when you want a reply or choose to add an attachment; opening the draft does not send it.'],
    ['#fb_download', 'Save feedback for later', 'Save feedback (.txt) downloads a local copy of the draft. Example: on an offline analysis computer, save the note and send it from a connected device later.'],
    ['#fb_consent, #fb_submit', 'Send feedback without providing an email', 'Send feedback uses the existing PASA Google Form without requesting a name, email, or sign-in. Choose a reaction and acknowledge the notice before sending. Google can receive normal connection metadata. Example: send a suggestion without a return address; if offline or receipt is unconfirmed, keep or save the draft for later.', 'The operator has disabled direct feedback or supplied an incomplete custom destination. Save a text draft or optionally compose an email instead.', '#pasa-feedback-actions'],
    ['#pasa-contacts-menu > button', 'Find contact and community links', 'Contacts groups Email, X (Twitter), LinkedIn, and Feedback. Example: use Feedback for an app suggestion or Email for a direct message. The tour opens no external destinations and sends nothing.'],
    ['#pasa-contacts-menu a[href^="mailto:"]', 'Contact PASA by email', 'Email opens a message addressed to the PASA contact. Example: include the app version and a concise description when asking about a reproducible problem.'],
    ['#pasa-contacts-menu a[href^="https://x.com"]', 'Find the X profile', 'This link opens the listed X profile in another tab. Example: use it to follow public updates; keep detailed app feedback in the Feedback or email route.'],
    ['#pasa-contacts-menu a[href*="linkedin.com"]', 'Find the LinkedIn profile', 'LinkedIn opens the listed professional profile. Example: use it for professional contact or to learn about the developer.'],
    ['#pasa-contact-feedback', 'Open Feedback from Contacts', 'Feedback is also available immediately below LinkedIn. Example: jump here from any analysis page when you notice something that could be clearer.'],
    ['.theme-menu > button', 'Adjust the interface appearance', 'Theme contains appearance and typography options. Example: choose a light theme in a bright lab or a dark theme in dim lighting. These choices change presentation.'],
    ['#appearance', 'Choose a theme for your screen', 'Auto follows the system; Light, Dark, Midnight Teal, High-Contrast, and Sepia / Warm are explicit alternatives. Example: try High-Contrast if you need more separation between text and background.'],
    ['#dyslexia_mode', 'Try the reading-friendly typography', 'Dyslexia-friendly changes font presentation, spacing, and line height. Example: turn it on while reading a long Help section and keep whichever setting is more comfortable for you.'],
    ['#pasa_tour_restart', 'Return to any tour chapter', 'Guided tour offers Quick and Detailed walkthroughs with separate progress. Use the chapter selector to revisit a subject, or pause and resume later. Example: return directly to Analysis settings when trying a new normalization method.']
  ], false);
  window.PASATourWorkspaceSteps = steps;
})();

